{
  "packet_id": "H6-T04-3",
  "claim_id": "C021",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C021.component",
    "value": "For a selected change, randomly assign eligible new accounts to the change or current experience if feasible.",
    "scope": "A feasibility-qualified experimental recommendation for eligible new accounts.",
    "provenance": {
      "refs": [
        {
          "source_id": "P013",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P013 supplies the assignment method, comparison, eligibility restriction and feasibility qualification."
    }
  },
  "signal_basis": {
    "component_id": "C021.signal_basis",
    "value": "Compare first-publication rates between the change and current experience over prespecified follow-up, assessing uncertainty and guardrails. Random assignment addresses the possibility that differences instead reflect account mix or roster timing.",
    "scope": "Eligible new accounts in the selected release test, with predefined measures and follow-up spanning an intended roster opportunity.",
    "provenance": {
      "refs": [
        {
          "source_id": "P013",
          "role": "SUPPORT"
        },
        {
          "source_id": "P014",
          "role": "SUPPORT"
        },
        {
          "source_id": "P022",
          "role": "SUPPORT"
        },
        {
          "source_id": "P035",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the comparison design, measurement bounds, observed signal and account-mix or timing concern motivating random assignment."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C021.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is needed to warrant this bounded experimental recommendation."
    }
  },
  "rationale": "Random assignment is warranted for evaluating the selected change because it supports a causal comparison while addressing systematic differences in account mix and roster timing. The frozen claim recommends a feasible experimental design; it does not assert improvement, establish a mechanism or authorize deployment.",
  "uncertainty": "Finite-sample imbalance and imprecise results remain possible, but do not undermine the recommendation to randomize when feasible.",
  "anomalies": []
}
